CustomField.formula:
IF(NOT(ISBLANK(State)),
    IF(CONTAINS($Label.Subregion_AMER_Pacific_Northwest,State + ";"),"Pacific Northwest",
        IF(State = "California" || State = "CA","California",
            IF(CONTAINS($Label.Subregion_AMER_Mountain_West,State + ";"),"Mountain West",
                IF(CONTAINS($Label.Subregion_AMER_Southwest,State + ";"),"Southwest",
                    IF(CONTAINS($Label.Subregion_AMER_Midwest,State + ";"),"Midwest",
                        IF(CONTAINS($Label.Subregion_AMER_Southeast,State + ";"),"Southeast",
                            IF(CONTAINS($Label.Subregion_AMER_Mid_Atlantic,State + ";"),"Mid Atlantic",
                                IF(CONTAINS($Label.Tri_State,State + ";"),"Tri State",
                                    IF(CONTAINS($Label.Subregion_AMER_Northeast,State + ";"),"Northeast","")
                                )
                            )
                        )
                    )
                )
            )
        )
    ),
    ""
)
